            const setDashboardMenu = (open) => { dashboardSidebar?.classList.toggle('-translate-x-full', !open); dashboardSidebar?.classList.toggle('translate-x-0', open); dashboardBackdrop?.classList.toggle('hidden', !open); dashboardBackdrop?.classList.toggle('opacity-0', !open); dashboardBackdrop?.classList.toggle('opacity-100', open); document.body.classList.toggle('overflow-hidden', open); };
            document.querySelector('[data-dashboard-open]')?.addEventListener('click', () => setDashboardMenu(true)); document.querySelector('[data-dashboard-close]')?.addEventListener('click', () => setDashboardMenu(false)); dashboardBackdrop?.addEventListener('click', () => setDashboardMenu(false)); dashboardSidebar?.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => setDashboardMenu(false)));
            const themeKey = 'travelconnect-dashboard-theme'; const savedTheme = localStorage.getItem(themeKey); const applyTheme = (dark) => { dashboardShell?.classList.toggle('dashboard-dark', dark); document.querySelector('[data-theme-icon]').innerHTML = dark ? '<path d="M12 3v2M12 19v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M3 12h2M19 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/><circle cx="12" cy="12" r="3"/>' : '<path d="M20.5 15.2A8.5 8.5 0 0 1 8.8 3.5 8.5 8.5 0 1 0 20.5 15.2Z"/>'; }; applyTheme(savedTheme === 'dark'); document.querySelector('[data-theme-toggle]')?.addEventListener('click', () => { const dark = !dashboardShell.classList.contains('dashboard-dark'); applyTheme(dark); localStorage.setItem(themeKey, dark ? 'dark' : 'light'); });
